// reviewApi.js
import api from "./axiosConfig";

export const fetchReviews = (params) => api.get("/reviews", { params });
export const fetchReview = (id) => api.get(`/reviews/${id}`);
export const createReview = (payload) => api.post("/reviews", payload);
